const U={game:null,blueprint:null,manifest:null,runId:null,researchId:null,timer:null,researchTimer:null,polling:false,researchPolling:false,foundationBuildId:null,foundationTimer:null,foundationPolling:false,foundationContext:null,editor:null,currentRevisionId:null,pipeline:null,previewMode:'DESKTOP',advancedLoaded:false,i6:null,i6ConceptId:null,i6Prototype:null,v3:{workspace:null,selected:null,loading:false,mounted:false,beforeAfter:null,syncedKey:''}};const $=id=>document.getElementById(id),esc=v=>GV.safe(v??"");
function notify(message,type=""){const el=$("universeMessage");el.textContent=message;el.className=`beta95-message ${type}`;}
function stat(value,label){return `<div class="b95-stat"><strong>${Number(value||0)}</strong><span>${esc(label)}</span></div>`;}
async function games(){
  const select=$("universeGame");if(!select)throw new Error("UNIVERSE_SELECTOR_MISSING");
  select.disabled=true;select.innerHTML='<option value="">Loading games and experiences…</option>';
  let data;
  try{data=await GV.api('/api/universe-builder-099/entities');}
  catch(error){select.innerHTML='<option value="">Could not load entities</option>';notify(`Could not load Game / Experience selector: ${error.message||'API_ENTITY_LIST_FAILED'}`,'error');throw error;}
  const entries=Array.isArray(data?.entries)?data.entries:[];
  const gamesList=entries.filter(x=>String(x.entityType||'GAME').toUpperCase()==='GAME');
  const experienceList=entries.filter(x=>String(x.entityType||'').toUpperCase()==='EXPERIENCE');
  const option=g=>`<option value="${esc(g.id)}">${esc(g.name)}${g.status&&g.status!=='PUBLISHED'?` [${esc(g.status)}]`:''}</option>`;
  const experienceOption=g=>`<option value="${esc(g.id)}">${esc(g.name)} — Experience · ${esc(g.parent?.name||'Parent game')}</option>`;
  if(!entries.length){select.innerHTML='<option value="">No Games or Experiences available</option>';select.disabled=true;notify('The entity API returned an empty list. Check classification and authorization.','error');return [];}
  select.innerHTML=`<optgroup label="GAMES">${gamesList.map(option).join('')}</optgroup>${experienceList.length?`<optgroup label="EXPERIENCES">${experienceList.map(experienceOption).join('')}</optgroup>`:''}`;
  select.disabled=false;
  const roblox=entries.find(g=>g.slug==='roblox'&&String(g.entityType||'GAME').toUpperCase()==='GAME');
  if(roblox)select.value=roblox.id;else if(entries[0])select.value=entries[0].id;
  return entries;
}
function renderBlueprint(data){U.blueprint=data;$("blueprint").innerHTML=data.categories.map(c=>`<label class="blueprint-option"><input type="checkbox" data-key="${esc(c.key)}" ${c.enabled?"checked":""}> <span>${esc(c.label)}</span><small class="b95-badge">${esc(c.recipeKey)}</small></label>`).join("");}
function renderManifest(manifest){U.manifest=manifest;if(!manifest){$("manifestSummary").innerHTML="";$("manifestItems").innerHTML='<p class="beta95-muted">Nenhum manifesto atual. O Build Entire pode criar um automaticamente.</p>';$("startBuild").disabled=false;$("startResearch").disabled=true;$("validateReadiness").disabled=true;return;}const s=manifest.summary||{};$("manifestSummary").innerHTML=stat(s.identified,"identificadas")+stat(s.ready,"prontas")+stat(s.needsResearch,"pesquisa")+stat(s.needsReview,"revisão")+stat(s.exists,"existentes");$("manifestItems").innerHTML=manifest.items.map(item=>`<article class="b95-row manifest-item"><strong>${esc(item.title)}</strong><span>${esc(item.wave)}</span><span class="b95-badge ${esc(item.status.toLowerCase())}">${esc(item.status)}</span><span class="beta95-muted">${esc(item.reason)}</span></article>`).join("");$("approveManifest").disabled=manifest.status==="APPROVED"||manifest.status==="BUILDING"||manifest.status==="COMPLETED";$("startBuild").disabled=false;$("startResearch").disabled=false;$("validateReadiness").disabled=false;}
