function renderGraph(graph){$("universeMap").innerHTML=graph.list.length?graph.list.map(item=>`<a class="b95-row" href="${esc(item.page?`/generated-page.html?id=${encodeURIComponent(item.page.id)}`:`/entity.html?id=${encodeURIComponent(item.id)}`)}"><div class="b95-row-head universe-entity-title"><strong>${esc(item.label)}</strong><span aria-hidden="true" class="universe-type-separator">·</span><span class="b95-badge">${esc(item.type)}</span></div><small>${item.related} relação(ões) · ${item.page?esc(item.page.status):"sem página"} · ${esc(item.planningStatus||"DISCOVERED")}</small></a>`).join(""):'<p class="beta95-muted">Nenhuma entidade no mapa.</p>';}
