async function openUniverse(){U.game=$('universeGame').value;const language=$('universeLanguage').value;notify('Carregando o Universe Builder Beta 0.99...');await loadFoundationContext();await loadExperienceEditor().catch(error=>{U.editor=null;$('interactionList').innerHTML=`<p class="beta95-muted">Pipeline avançado indisponível: ${esc(error.message)}</p>`;});try{const [basic,blueprint,latest,coverage,graph]=await Promise.all([GV.api(`/api/universe/games/${encodeURIComponent(U.game)}/basic-overview`),GV.api(`/api/universe/games/${encodeURIComponent(U.game)}/blueprint?language=${language}`),GV.api(`/api/universe/games/${encodeURIComponent(U.game)}/manifests/latest?language=${language}`),GV.api(`/api/universe/games/${encodeURIComponent(U.game)}/coverage?language=${language}`),GV.api(`/api/universe/games/${encodeURIComponent(U.game)}/graph?language=${language}`)]);renderBasicOverview(basic);renderBlueprint(blueprint.blueprint);renderManifest(latest.manifest);renderCoverage(coverage.coverage);renderGraph(graph.graph);}catch(error){$('basicOverview').innerHTML=`<p class="beta95-muted">Legacy compatibility data unavailable for this entity: ${esc(error.message)}</p>`;$('blueprint').innerHTML='';$('coverage').innerHTML='';$('universeMap').innerHTML='';renderManifest(null);}notify('Universe carregado. Conteúdo, imagens, aparência, interações e Preview estão prontos para revisão; nenhuma API key é necessária.','good');}
async function saveBlueprint(){const categories=[...$("blueprint").querySelectorAll("input[data-key]")].map((input,index)=>({key:input.dataset.key,label:input.nextElementSibling.textContent,enabled:input.checked,position:index}));const data=await GV.api(`/api/universe/games/${encodeURIComponent(U.game)}/blueprint`,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({categories,status:"VALIDATED"})});renderBlueprint(data.blueprint);notify("Blueprint versionado sem excluir páginas existentes.","good");}
