function renderV2Status(status){const m=status.metrics||{},q=status.queues||{};$("buildState").innerHTML=`<div class="b95-row"><div class="b95-row-head"><strong>Universe Builder 3.0 · ${status.active?"PROCESSANDO":"ESTÁVEL"}</strong><span class="b95-badge">0.986</span></div><small>${m.discovered||0} descobertas · ${m.pagesBuilt||0} páginas · ${m.imagesReady||0} imagens · ${m.indexed||0} indexadas · manifesto: ${status.manifestId?"SIM":"AGUARDANDO DISCOVERY"} · aprovação manual: NÃO</small></div>`+Object.entries(q).map(([type,states])=>`<div class="b95-row"><div class="b95-row-head"><strong>${esc(type)}</strong><span class="b95-badge">${Object.values(states||{}).reduce((a,b)=>a+Number(b||0),0)}</span></div><small>${Object.entries(states||{}).map(([k,v])=>`${esc(k)} ${Number(v||0)}`).join(" · ")||"sem jobs"}</small></div>`).join("");return !status.active;}
