function renderPrePublicRun(run){const jobs=run.jobs||[],done=jobs.filter(j=>["PASS","SKIPPED"].includes(j.status)).length,blocked=jobs.filter(j=>["BLOCKED","FAILED","NEEDS_REVIEW"].includes(j.status)).length,progress=jobs.length?Math.round(done/jobs.length*100):0;$("buildState").innerHTML=`<div class="b95-row"><div class="b95-row-head"><strong>${esc(run.currentStage)} · ${esc(run.status)}</strong><span>${progress}%</span></div><div class="b95-progress"><span style="width:${progress}%"></span></div><small>${done}/${jobs.length} jobs concluídos · ${blocked} bloqueados/revisão · checkpoint ${esc(run.updatedAt)}</small></div>`+["RESEARCH","BUILD","IMAGE","RELATIONSHIP","INDEX","REVIEW"].map(type=>{const rows=jobs.filter(j=>j.jobType===type),pass=rows.filter(j=>j.status==="PASS").length,pending=rows.filter(j=>["QUEUED","RUNNING"].includes(j.status)).length,bad=rows.filter(j=>["BLOCKED","FAILED","NEEDS_REVIEW"].includes(j.status)).length;return `<div class="b95-row"><div class="b95-row-head"><strong>${type}</strong><span class="b95-badge">${pass}/${rows.length}</span></div><small>${pending} pendente(s) · ${bad} bloqueado(s)/revisão</small></div>`;}).join("");return new Set(["COMPLETED","BLOCKED","FAILED","CANCELLED"]).has(run.status);}
