  $('simpleContentStatus').textContent=pages?'Pronto':'Aguardando';$('simpleContent').innerHTML=`${progressBar(contentPct)}<p><strong>${pages}</strong> página(s) · <strong>${sections}</strong> seção(ões)</p><p>${facts} fatos úteis/validados</p>`;
  $('simpleImagesStatus').textContent=!total?'Aguardando conteúdo':missing?'Precisa de atenção':'Pronto';$('simpleImages').innerHTML=!total?`${progressBar(0)}<p><strong>Aguardando conteúdo</strong></p><p>As necessidades visuais ainda não foram declaradas para esta revisão.</p>`:`${progressBar(imgPct)}<p><strong>${resolved} de ${total}</strong> imagens resolvidas</p>${missing?`<p>Faltam ${missing} imagem(ns) obrigatória(s).</p>`:'<p>As imagens obrigatórias estão resolvidas.</p>'}`;
  $('simpleAppearanceStatus').textContent=visual>=80&&gap>=80?'Boa':visual?'Precisa melhorar':'Aguardando';$('simpleAppearance').innerHTML=`${progressBar(visual)}<p>Qualidade visual: <strong>${visual}%</strong></p><p>Continuidade visual: <strong>${gap}%</strong></p>${visual&&visual<80?'<p>A página ainda pode ficar menos rarefeita.</p>':''}`;
  $('simpleInteractionsStatus').textContent=draft?'Revisar':readyInteractions?'Pronto':'Aguardando';$('simpleInteractions').innerHTML=`${progressBar(interactionPct)}<p><strong>${readyInteractions}</strong> pronta(s) · <strong>${draft}</strong> rascunho(s)</p>`;
  const ready=pub==='READY'||pub==='PUBLISHED';$('simplePublishTitle').textContent=ready?(pub==='PUBLISHED'?'Publicado':'Pronto para publicar'):'Ainda não pode publicar';const card=document.querySelector('.gi099i5-publish-check');card?.classList.toggle('ready',ready);card?.classList.toggle('blocked',!ready);$('simplePublishChecklist').innerHTML=ready?`<div class="b95-row"><strong>✓ Tudo certo</strong><small>Preview ${esc(preview)} · publicação ${esc(pub)}</small></div>`:(blockers.length?blockers.slice(0,6).map(x=>`<div class="b95-row"><strong>• ${esc(plainIssue(x))}</strong></div>`).join(''):'<p class="beta95-muted">Construa ou atualize a Preview para verificar o que falta.</p>');
