function renderResearchContentI4(data){const pipeline=data?.pipeline||{},structure=data?.structure||{},pages=structure.pages||[],validation=data?.validation||{},facts=validation.research?.factsValidated||0,vars=pipeline.images?.variables||[];$('i4ResearchStatus').textContent=validation.domains?.CONTENT_STATUS||'NOT_STARTED';$('i4ResearchSummary').innerHTML=stat(validation.research?.sourcesDiscovered||0,'sources discovered')+stat(facts,'validated facts')+stat(pages.length,'pages')+stat(pipeline.structure?.sections||0,'sections')+stat(vars.length,'image variables');const comps=pipeline.composition?.entries||[];$('i4ResearchContent').innerHTML=pages.length?pages.map(page=>{const sections=[...(page.sections||[]),...(page.tabs||[]).flatMap(t=>t.sections||[])];return `<article class="b95-row gi099i4-content-page"><div class="b95-row-head"><strong>${esc(page.titleText||page.canonicalKey)}</strong><span class="b95-badge">${sections.length} sections</span></div>${sections.map(section=>{const v=vars.find(x=>x.sectionId===section.id),c=comps.find(x=>x.sectionId===section.id);return `<div class="gi099i4-content-section"><div><strong>${esc(section.titleText||section.canonicalKey)}</strong><small>${esc(section.sectionType||'TEXT')} · ${v?esc(v.variableKey):'No image variable'}${v?.required?' · REQUIRED':''}</small></div>${c?`<label>Composition<select data-i4-composition-select="${esc(c.id)}">${(U.editor?.contracts?.compositionLayouts||[]).map(x=>`<option ${x===c.layoutVariant?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`:''}</div>`;}).join('')}</article>`}).join(''):'<p class="beta95-muted">No structured draft/published pages are available yet.</p>';}
