function renderImageVariablesI4(data){const p=data?.pipeline||{},img=p.images||{},vars=img.variables||[];$('i4ImageSummary').innerHTML=stat(img.total||vars.length,'variables')+stat(img.resolved||vars.filter(x=>x.status==='RESOLVED').length,'resolved')+stat(img.required||vars.filter(x=>x.required).length,'required')+stat(img.unresolvedRequired||vars.filter(x=>x.required&&x.status!=='RESOLVED').length,'missing required');$('i4ImageVariables').innerHTML=vars.length?vars.map(v=>{const bound=v.binding?.asset;return `<article class="gi099i4-image-variable ${v.required?'required':''}"><div class="b95-row-head"><div><strong>${esc(v.label||v.variableKey)}</strong><small>${esc(v.variableKey)}</small></div><span class="b95-badge">${esc(v.status)}</span></div><p>${esc(v.semanticIntent||'Authentic game-sourced visual required.')}</p>${bound?`<div class="gi099i4-bound-asset"><img src="${esc(bound.variants?.card||bound.imageUrl)}" alt="${esc(bound.semanticRole||'Resolved game asset')}" loading="lazy"><div><strong>Resolved → ${esc(bound.assetKey||bound.id)}</strong><small>${esc(bound.sourceType||'APPROVED')}</small></div></div>`:`<div class="b95-actions"><button class="b95-button secondary" type="button" data-i4-image-action="search" data-variable-id="${esc(v.id)}">Search again</button></div><div class="gi099i4-candidates">${(v.candidates||[]).slice(0,4).map(c=>imageCandidateMarkup(v,c)).join('')||'<small>No candidate yet. Missing is preferred over fake artwork.</small>'}</div>`}</article>`}).join(''):'<p class="beta95-muted">No image variables. Run Research & Content first.</p>';}
