function renderInteractivePreviewI4(record){const snap=record?.snapshot||record;if(!snap?.structure){$('experiencePreview').innerHTML='<p class="beta95-muted">No current Interactive Preview. Generate one after content/images change.</p>';return;}const vars=snap.variables||[],comps=snap.compositions||[],pages=snap.structure.pages||[];const assetByVar=id=>vars.find(v=>v.id===id)?.binding?.asset||null;$('i4PreviewViewport').dataset.mode=U.previewMode||snap.viewportMode||'DESKTOP';$('i4PreviewMeta').innerHTML=statusBadge('Snapshot',record.status||'READY')+statusBadge('Density',snap.density||'RICH')+statusBadge('Visual Gap',`${snap.visualGap?.score??0}%`)+statusBadge('Content',snap.versions?.contentVersion||'—')+statusBadge('Images',snap.versions?.imageVersion||'—');$('experiencePreview').innerHTML=`<div class="gi099i4-preview-shell"><header><div><p class="beta95-kicker">${esc(snap.entity?.entityType||'GAME')} · BETA 0.99 PREVIEW</p><h2>${esc(snap.entity?.name||'Universe')}</h2></div><span class="b95-badge">${esc(snap.density||'RICH')}</span></header><nav class="gi099i4-preview-nav">${pages.map((p,i)=>`<button type="button" data-i4-preview-page="${esc(p.canonicalKey)}" class="${i===0?'active':''}" data-gi-element-key="PAGE_NAV:${esc(p.canonicalKey)}">${esc(p.titleText||p.canonicalKey)}</button>`).join('')}</nav><div class="gi099i4-preview-info" aria-live="polite"></div>${pages.map((p,pi)=>{const sections=[...(p.sections||[]),...(p.tabs||[]).flatMap(t=>t.sections||[])];return `<div class="gi099i4-preview-page ${pi===0?'active':''}" data-preview-page="${esc(p.canonicalKey)}" data-gi-element-key="PAGE:${esc(p.canonicalKey)}"><h3>${esc(p.titleText||p.canonicalKey)}</h3>${sections.map(section=>{const c=comps.find(x=>x.sectionId===section.id),a=assetByVar(c?.primaryVariableId),bg=assetByVar(c?.backgroundVariableId),layout=c?.layoutVariant||'TEXT_LEFT_VISUAL_RIGHT';return `<section class="gi099i4-preview-section" data-layout="${esc(layout)}" data-section-key="${esc(section.canonicalKey)}" data-gi-element-key="SECTION:${esc(section.canonicalKey)}">${bg?`<img class="gi099i4-preview-bg" src="${esc(bg.variants?.section||bg.imageUrl)}" alt="" loading="lazy">`:''}<div class="gi099i4-preview-copy"><small>${esc(section.sectionType||'TEXT')}</small><h4>${esc(section.titleText||section.canonicalKey)}</h4><p>${esc(previewSectionText(section)||'Ainda não há conteúdo verificado nesta seção.')}</p></div>${a?`<button type="button" class="gi099i4-preview-asset" data-gi-element-key="ASSET:${esc(String(a.assetKey||'').toUpperCase())}" aria-label="${esc(a.visualFamily||a.assetKey||'Game visual')}"><img src="${esc(a.variants?.section||a.variants?.card||a.imageUrl)}" alt="${esc(a.provenance?.altText||a.visualFamily||a.assetKey||'Game visual')}" loading="lazy" decoding="async"></button>`:`<div class="gi099i4-preview-missing">Real game asset unresolved</div>`}</section>`;}).join('')}</div>`}).join('')}</div>`;bindPreviewInteractionsI4(snap);}
function bindPreviewInteractionsI4(snap){const root=$('experiencePreview'),interactions=(snap.interactions||[]).filter(x=>['DRAFT','VALIDATED','PUBLISHED'].includes(x.status));root.querySelectorAll('[data-i4-preview-page]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-i4-preview-page]').forEach(x=>x.classList.toggle('active',x===b));root.querySelectorAll('[data-preview-page]').forEach(x=>x.classList.toggle('active',x.dataset.previewPage===b.dataset.i4PreviewPage));}));function execute(row,node){const action=row.actionType,target=String(row.targetId||'');if(action==='SCROLL_TO'){const t=[...root.querySelectorAll('[data-section-key],[data-preview-page]')].find(x=>String(x.dataset.sectionKey||x.dataset.previewPage||'').toUpperCase()===target.toUpperCase());if(t){const page=t.closest('[data-preview-page]');if(page&&!page.classList.contains('active'))root.querySelector(`[data-i4-preview-page="${CSS.escape(page.dataset.previewPage)}"]`)?.click();t.scrollIntoView({behavior:'smooth',block:'center'});}}else if(['PLAY_ANIMATION','CHANGE_STATE'].includes(action)){node.classList.remove('gi099i4-preview-pulse');void node.offsetWidth;node.classList.add('gi099i4-preview-pulse');}else{root.querySelector('.gi099i4-preview-info').textContent=row.parameters?.message||row.parameters?.label||`${action}${target?` → ${target}`:''}`;}}root.addEventListener('click',e=>{const node=e.target.closest('[data-gi-element-key]');if(!node)return;const key=String(node.dataset.giElementKey||'').toUpperCase(),row=interactions.find(x=>String(x.elementKey||'').toUpperCase()===key&&x.eventType==='CLICK');if(row){e.preventDefault();execute(row,node);}});root.addEventListener('mouseover',e=>{const node=e.target.closest('[data-gi-element-key]');if(!node)return;const key=String(node.dataset.giElementKey||'').toUpperCase(),row=interactions.find(x=>String(x.elementKey||'').toUpperCase()===key&&x.eventType==='HOVER');if(row)execute(row,node);});}
function renderFinalReportI4(report={},validation={}){const summary=report.summary||{},m=report.metrics||{},blockers=report.blockers||validation.blockers||[],warnings=report.warnings||validation.warnings||[];$('i4FinalReport').innerHTML=`<div class="gi099i4-report-grid">${Object.entries(summary).map(([k,v])=>`<div><span>${esc(k.toUpperCase())}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="b95-row"><strong>Metrics</strong><small>${Number(m.facts||0)} facts · ${Number(m.pages||0)} pages · ${Number(m.sections||0)} sections · ${Number(m.imageVariablesResolved||0)}/${Number(m.imageVariables||0)} images resolved · Visual ${Number(m.visualCoverage||0)}% · Visual Gap ${Number(m.visualGapQuality||0)}% · ${Number(m.interactions||0)} interactions</small></div>${blockers.length?`<div class="gi099i4-report-issues blockers"><strong>BLOCKERS</strong>${blockers.map(x=>`<p>${esc(issueText(x))}</p>`).join('')}</div>`:'<div class="gi099i4-report-issues"><strong>No publication blockers.</strong></div>'}${warnings.length?`<div class="gi099i4-report-issues"><strong>WARNINGS</strong>${warnings.map(x=>`<p>${esc(issueText(x))}</p>`).join('')}</div>`:''}`;renderTopStatus(validation,report);}
function renderFoundationPreview(preview){if(!preview)return;U.currentRevisionId=preview.revision?.id||U.currentRevisionId;U.pipeline=preview.pipeline||U.pipeline;const rev=preview.revision||{},pages=preview.structure?.pages||[],events=(preview.events||[]).slice(-16).reverse(),summary=preview.sourceSummary||{},validation=preview.validation||{},report=preview.report||{};$('foundationPreviewOutput').innerHTML=`<div class="b95-row"><div class="b95-row-head"><strong>Revision ${esc(rev.revision_number||'—')}</strong><span class="b95-badge">${esc(rev.status||'NO REVISION')}</span></div><small>${Number(summary.total||0)} source records · ${pages.length} page(s) · ${Number(preview.pipeline?.images?.resolved||0)}/${Number(preview.pipeline?.images?.total||0)} image variable(s) resolved · Visual Gap ${Number(preview.pipeline?.composition?.visualGap?.score||0)}%</small></div>${events.map(e=>`<div class="b95-row"><div class="b95-row-head"><strong>${esc(e.stage)}</strong><span class="b95-badge">${esc(e.eventType)}</span></div><small>${esc(e.message)}</small></div>`).join('')}`;renderFinalReportI4(report,validation);if(preview.pipeline?.preview)renderInteractivePreviewI4(preview.pipeline.preview);}
async function refreshFoundationPreview(){if(!U.foundationBuildId)return;const data=await GV.api(`/api/universe-builder-099/builds/${encodeURIComponent(U.foundationBuildId)}/preview`);renderFoundationPreview(data.preview);renderFoundationBuild(data.preview?.build);if(data.preview?.revision?.id){U.currentRevisionId=data.preview.revision.id;await loadExperienceEditor(U.currentRevisionId);}return data.preview;}
async function pollFoundation099(){if(!U.foundationBuildId||U.foundationPolling||document.hidden)return;U.foundationPolling=true;try{const data=await GV.api(`/api/universe-builder-099/builds/${encodeURIComponent(U.foundationBuildId)}`),terminal=renderFoundationBuild(data.build);if(terminal){clearTimeout(U.foundationTimer);await refreshFoundationPreview();notify(data.build.status==='FAILED'?'A construção falhou com segurança; a revisão publicada anterior continua intacta.':'Construção concluída. Resolva o que faltar e atualize a Preview antes de publicar.',data.build.status==='FAILED'?'error':'good');return;}}catch(error){notify(error.message,'error');}finally{U.foundationPolling=false;}clearTimeout(U.foundationTimer);U.foundationTimer=setTimeout(pollFoundation099,1400);}
async function startFoundation099(){if(!U.game)throw new Error('Select an entity first.');const data=await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/builds`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({scope:$('foundationScope').value,language:$('universeLanguage').value}),timeout:60000});U.foundationBuildId=data.build.id;U.currentRevisionId=null;renderFoundationBuild(data.build);$('foundationPreviewOutput').innerHTML='';notify(`Construção iniciada: pesquisa → conteúdo → imagens reais → composição → Preview.`,'good');pollFoundation099();}
