async function cancelFoundation099(){if(!U.foundationBuildId)return;const data=await GV.api(`/api/universe-builder-099/builds/${encodeURIComponent(U.foundationBuildId)}/cancel`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});renderFoundationBuild(data.build);notify('Cancellation requested.','good');}
async function loadExperienceEditor(revisionId=U.currentRevisionId){if(!U.game)return null;const q=revisionId?`&revisionId=${encodeURIComponent(revisionId)}`:'';const data=await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/editor?language=${encodeURIComponent($('universeLanguage').value)}${q}`);U.editor=data;U.pipeline=data.pipeline||null;renderExperienceEditor(data);refreshBuilderV3().then(()=>syncBuilderV3IssuesOnce()).catch(error=>renderBuilderV3Error(error));return data;}
function renderExperienceEditor(data){U.editor=data;U.pipeline=data.pipeline||U.pipeline;renderSimpleI5(data);renderI6State(data?.i6||null,data);renderFinalReportI4(data?.report||{},data?.validation||{});const i6Revision=data?.i6?.revisionState;const currentPreview=data?.pipeline?.preview;if(currentPreview?.status==='READY')renderInteractivePreviewI4(currentPreview);else if(i6Revision?.currentStatus==='BUILDING'&&data?.i6?.lastValid?.pipeline?.preview)renderInteractivePreviewI4(data.i6.lastValid.pipeline.preview);else renderInteractivePreviewI4(currentPreview);$('editorClassification').textContent='Beta 0.99';if(U.advancedLoaded||$('advancedBuilder')?.open)renderAdvancedI5(data);}
