function renderValidationI3(validation={}){const domains=validation.domains||validation,visual=validation.visual||{},blockers=validation.blockers||[],warnings=validation.warnings||[],publication=domains.PUBLICATION_STATUS||'NOT_STARTED';$('publicationStatusI3').textContent=publication;const order=['STRUCTURE_STATUS','RESEARCH_STATUS','CONTENT_STATUS','IMAGES_STATUS','MEDIA_STATUS','VISUAL_GROUNDING_STATUS','INTERACTION_STATUS','PREVIEW_STATUS','PERFORMANCE_STATUS','PUBLICATION_STATUS'],coverage=Number(visual.coverageScore??0),gap=Number(visual.visualGap?.score??0);$('validationI3').innerHTML=`<div class="gi099i3-validation-grid">${order.map(k=>`<div class="gi099i3-validation-domain"><span>${esc(k.replace('_STATUS','').replaceAll('_',' '))}</span><strong>${esc(domains[k]||'NOT_STARTED')}</strong></div>`).join('')}</div><div class="b95-row"><strong>Visual audit</strong><small>Coverage ${coverage}% · I5 target ${Number(visual.i5Target??visual.i4Target??0)}% · Visual Gap quality ${gap}%</small></div>${blockers.length?`<div class="gi099i3-validation-issues"><strong>Blockers</strong>${blockers.map(x=>`<p>${esc(issueText(x))}</p>`).join('')}</div>`:''}${warnings.length?`<div class="gi099i3-validation-issues"><strong>Warnings</strong>${warnings.map(x=>`<p>${esc(issueText(x))}</p>`).join('')}</div>`:''}`;renderTopStatus(validation,U.editor?.report||{});}
