  const resume=$('foundationResume');if(resume){resume.hidden=!['INTERRUPTED','PARTIAL','FAILED'].includes(buildStatus);resume.disabled=resume.hidden;}const canDownstream=valid;$('simpleFindImages').disabled=!canDownstream;$('discoverIdentityI6').disabled=!canDownstream;$('discoverInteractionsI6').disabled=!canDownstream;$('enhanceI6').disabled=!canDownstream;$('foundationPreview').disabled=!valid;$('foundationPublish').disabled=!valid;
