function prototypeMarkupI6(p){const cfg=p?.config||{},items=Array.isArray(cfg.items)?cfg.items:[],steps=Array.isArray(cfg.steps)?cfg.steps:[],kind=cfg.kind||p?.prototypeType||'INSPECT';if(kind==='ASSEMBLE')return `<h3>Monte a experiência</h3><div class="gi099i6-prototype-options">${steps.map((x,i)=>`<button type="button" class="b95-button secondary" data-i6-proto-option="${i}">${esc(x)}</button>`).join('')}</div><button class="b95-button" type="button" data-i6-proto-run>Concluir</button><div class="gi099i6-prototype-result" data-i6-proto-result>Escolha os elementos e teste a composição.</div>`;if(kind==='TIMING')return `<h3>Mini experiência de timing</h3><p>Teste o momento da ação.</p><button class="b95-button" type="button" data-i6-proto-run>${esc(cfg.buttonLabel||'Ação')}</button><div class="gi099i6-prototype-result" data-i6-proto-result>Pronto para testar.</div>`;return `<h3>${esc(kind==='RANDOMIZE'?'Sorteio':kind==='REVEAL'?'Revelar conteúdo':kind==='EXPLORE'?'Explorar opções':'Escolha uma opção')}</h3><div class="gi099i6-prototype-options">${items.map((x,i)=>`<button type="button" class="b95-button secondary" data-i6-proto-option="${i}">${esc(x)}</button>`).join('')}</div><button class="b95-button" type="button" data-i6-proto-run>${esc(cfg.buttonLabel||'Testar')}</button><div class="gi099i6-prototype-result" data-i6-proto-result>Use os controles para testar esta Preview.</div>`;}
function bindPrototypeI6(){const root=$('interactionPreviewCanvasI6');if(!root)return;let selected=[];root.onclick=e=>{const option=e.target.closest('[data-i6-proto-option]'),run=e.target.closest('[data-i6-proto-run]'),result=root.querySelector('[data-i6-proto-result]'),cfg=U.i6Prototype?.config||{};if(option){option.classList.toggle('active');const text=option.textContent.trim();selected=selected.includes(text)?selected.filter(x=>x!==text):[...selected,text];if(result)result.textContent=`Selecionado: ${selected.join(' · ')||'nenhum'}`;}if(run&&result){const items=Array.isArray(cfg.items)?cfg.items:[];if(cfg.kind==='RANDOMIZE'&&items.length)result.textContent=`Resultado: ${items[Math.floor(Math.random()*items.length)]}`;else if(cfg.kind==='REVEAL')result.textContent=`Aberto: ${items[0]||'conteúdo contextual'}`;else if(cfg.kind==='TIMING')result.textContent='Ação registrada. Esta é uma simulação informativa leve.';else result.textContent=`Resultado da Preview: ${selected.join(' · ')||items[0]||'experiência testada'}`;}};}
