function ub3BodyText(content={}){if(!content||typeof content!=='object')return String(content||'');const lang=$('universeLanguage')?.value||'pt-BR',translated=content.translations?.[lang];if(typeof content.body==='string')return content.body;if(typeof content.text==='string')return content.text;if(typeof content.canonical==='string')return content.canonical;if(Array.isArray(content.canonicalClaims))return content.canonicalClaims.join('\n\n');if(Array.isArray(translated))return translated.join('\n\n');if(typeof translated==='string')return translated;return '';}
function ub3Nodes(structure=[]){const out=[];for(const page of structure||[]){out.push({...page,level:0});for(const section of page.sections||[])out.push({...section,level:1,parentType:'PAGE',parentId:page.id});for(const tab of page.tabs||[]){out.push({...tab,level:1,parentType:'PAGE',parentId:page.id});for(const section of tab.sections||[])out.push({...section,level:2,parentType:'TAB',parentId:tab.id});}}return out;}
function ub3Metrics(){const editor=U.editor||{},m=editor.report?.metrics||{},pipeline=editor.pipeline||U.pipeline||{},images=pipeline.images||{},inter=U.i6?.current?.interactions||{},auth=U.i6?.current?.authorization||{},validation=editor.validation||{},domains=validation.domains||validation;return {pages:Number(m.pages||pipeline.structure?.pages?.length||0),sections:Number(m.sections||0),facts:Number(m.facts||U.i6?.current?.research?.usefulFacts||0),imagesTotal:Number(m.imageVariables||images.total||0),imagesResolved:Number(m.imageVariablesResolved||images.resolved||0),interactions:Number(m.interactions||inter.approved||0),pending:Number(auth.count||0),blockers:(validation.blockers||editor.report?.blockers||[]).length,warnings:(validation.warnings||editor.report?.warnings||[]).length,preview:String(domains.PREVIEW_STATUS||'NOT_STARTED'),mobile:String(domains.PREVIEW_STATUS||'NOT_STARTED'),performance:String(domains.PERFORMANCE_STATUS||'NOT_STARTED'),publication:String(domains.PUBLICATION_STATUS||'NOT_STARTED')};}
function ub3MountPreview(){if(U.v3.mounted)return;const mount=$('ub3PreviewMount'),viewport=$('i4PreviewViewport');if(!mount||!viewport)return;mount.innerHTML='';mount.appendChild(viewport);U.v3.mounted=true;}
function renderBuilderV3Error(error){const tree=$('ub3UniverseTree');if(tree)tree.innerHTML=`<div class="gi-ub3-tree-empty">V3 indisponível: ${esc(error?.message||'WORKSPACE_LOAD_FAILED')}</div>`;}
function renderBuilderV3Stages(){const root=$('ub3PipelineStages');if(!root)return;const stages=['RESEARCH','STRUCTURE','CONTENT','IMAGES','IDENTITY','INTERACTIONS','VALIDATION'],raw=String(U.foundationBuild?.currentStage||U.foundationBuild?.stage||'').toUpperCase(),aliases={RESEARCH_REFRESH:'RESEARCH',CONTENT_REFRESH:'CONTENT',IMAGE_REFRESH:'IMAGES',IDENTITY_RESEARCH:'IDENTITY',INTERACTION_REFRESH:'INTERACTIONS',STRUCTURE_REVIEW:'STRUCTURE',MEDIA_REFRESH:'IMAGES',TOPIC_REFRESH:'CONTENT',TECHNICAL_REFRESH:'VALIDATION'},current=aliases[raw]||raw,status=String(U.foundationBuild?.status||'').toUpperCase(),idx=stages.indexOf(current);root.querySelectorAll('[data-stage]').forEach((el,i)=>{el.classList.toggle('active',status==='RUNNING'&&i===idx);el.classList.toggle('done',status==='COMPLETED'||idx>=0&&i<idx);});}
function renderBuilderV3Tree(){const tree=$('ub3UniverseTree'),count=$('ub3TreeCount');if(!tree)return;const nodes=ub3Nodes(U.v3.workspace?.structure||[]);if(count)count.textContent=String(nodes.length);if(!nodes.length){tree.innerHTML='<div class="gi-ub3-tree-empty">Nenhuma página construída nesta revisão.</div>';return;}const selected=U.v3.selected;tree.innerHTML=nodes.map(n=>`<button type="button" class="gi-ub3-tree-item ${n.locked?'locked':''} ${selected?.type===n.type&&selected?.id===n.id?'active':''}" data-level="${Number(n.level||0)}" data-ub3-select-type="${esc(n.type)}" data-ub3-select-id="${esc(n.id)}"><span class="gi-ub3-tree-row"><span class="gi-ub3-tree-icon">${n.type==='PAGE'?'▣':n.type==='TAB'?'▸':'•'}</span><span class="gi-ub3-tree-title">${esc(n.title||n.key)}</span><span class="gi-ub3-tree-state">${n.locked?'LOCK':' '+esc(n.status||'')}</span></span></button>`).join('');}
function ub3FindNode(type,id){return ub3Nodes(U.v3.workspace?.structure||[]).find(n=>n.type===type&&n.id===id)||null;}
function renderBuilderV3Inspector(){const root=$('ub3Inspector'),typeLabel=$('ub3InspectorType'),n=U.v3.selected;if(!root)return;if(!n){if(typeLabel)typeLabel.textContent='—';root.innerHTML='<div class="gi-ub3-inspector-empty">Selecione uma página, aba ou seção na árvore ou na Preview.</div>';return;}if(typeLabel)typeLabel.textContent=n.type;const meta=`<div class="gi-ub3-inspector-meta"><span>${esc(n.type)}</span><span>${esc(n.status||'DRAFT')}</span><span>${esc(n.ownership||'UNIVERSE_BUILDER')}</span><span>${n.locked?'LOCKED':'AUTO'}</span></div>`;if(n.type!=='SECTION'){root.innerHTML=`<h4>${esc(n.title||n.key)}</h4>${meta}<label>Layout<input value="${esc(n.layoutVariant||'STANDARD')}" disabled></label><label>Identity<input value="${esc(n.identityVariant||'')}" disabled></label><div class="b95-actions"><button type="button" class="b95-button secondary" data-ub3-action="toggle-lock" data-locked="${n.locked?'1':'0'}">${n.locked?'Permitir mudanças automáticas':'Bloquear versão'}</button></div><p class="beta95-muted">Edição detalhada de páginas e abas continua no Modo Avançado; o lock V3 já protege a composição contra alterações automáticas compatíveis.</p>`;return;}const body=ub3BodyText(n.content||{});root.innerHTML=`<h4>${esc(n.title||n.key)}</h4>${meta}<label>Título<input id="ub3EditTitle" maxlength="220" value="${esc(n.title||'')}"></label><label>Conteúdo<textarea id="ub3EditBody" maxlength="16000">${esc(body)}</textarea></label><label>Layout<select id="ub3EditLayout">${['STANDARD','TEXT_LEFT_VISUAL_RIGHT','VISUAL_LEFT_TEXT_RIGHT','FULL_BLEED','CARDS','TIMELINE','GRID','FEATURE'].map(x=>`<option ${x===(n.layoutVariant||'STANDARD')?'selected':''}>${x}</option>`).join('')}</select></label><div class="b95-actions"><button type="button" class="b95-button" data-ub3-action="save-section">Salvar + proteger</button><button type="button" class="b95-button secondary" data-ub3-action="toggle-lock" data-locked="${n.locked?'1':'0'}">${n.locked?'Permitir mudanças automáticas':'Bloquear versão'}</button></div><p class="beta95-muted">Alterações manuais são persistidas e protegidas. Regenerações automáticas devem respeitar o lock.</p>`;}
function renderBuilderV3Issues(){const root=$('ub3Issues'),count=$('ub3IssueCount'),issues=U.v3.workspace?.issues||[];if(count)count.textContent=String(issues.length);if(!root)return;root.innerHTML=issues.length?issues.map(i=>`<article class="gi-ub3-issue ${String(i.priority||'').toLowerCase()}"><strong>${esc(i.priority)} · ${esc(i.title)}</strong><small>${esc(i.description||i.category)}</small></article>`).join(''):'<p class="beta95-muted">✓ Nenhuma decisão pendente sincronizada.</p>';}
function renderBuilderV3Quality(){const root=$('ub3Quality'),pub=$('ub3PublishState');if(!root)return;const m=ub3Metrics(),row=(label,value,state='')=>`<div class="gi-ub3-quality-row"><span>${esc(label)}</span><strong class="${state}">${esc(value)}</strong></div>`;root.innerHTML=row('Conteúdo',`${m.pages} páginas · ${m.sections} seções`,m.pages?'ok':'warn')+row('Fontes / fatos',String(m.facts),m.facts?'ok':'warn')+row('Imagens',`${m.imagesResolved}/${m.imagesTotal}`,m.imagesTotal&&m.imagesResolved>=m.imagesTotal?'ok':m.imagesResolved?'warn':'bad')+row('Interações',String(m.interactions),m.interactions?'ok':'warn')+row('Preview',m.preview,['READY','VALID','PUBLISHED'].includes(m.preview)?'ok':'warn')+row('Performance',m.performance,['READY','OK','VALID'].includes(m.performance)?'ok':'warn')+row('Pendências',String((U.v3.workspace?.issues||[]).length),(U.v3.workspace?.issues||[]).some(x=>x.priority==='BLOCKING')?'bad':(U.v3.workspace?.issues||[]).length?'warn':'ok');const blocked=m.blockers>0||(U.v3.workspace?.issues||[]).some(x=>x.priority==='BLOCKING')||!['READY','VALID','PUBLISHED'].includes(m.publication);if(pub){pub.className=`gi-ub3-publish ${blocked?'blocked':'ready'}`;pub.innerHTML=`<strong>${blocked?'NÃO PRONTO':'PRONTO PARA PUBLICAR'}</strong><small>${blocked?`${m.blockers} bloqueio(s) · ${(U.v3.workspace?.issues||[]).length} decisão(ões)`:'Validação e pendências resolvidas.'}</small>`;}const ba=$('ub3BeforeAfter');if(ba&&U.v3.beforeAfter){const b=U.v3.beforeAfter.before,a=U.v3.beforeAfter.after;ba.hidden=false;ba.innerHTML=`<div><strong>ANTES</strong>Imagens ${b.imagesResolved}/${b.imagesTotal}<br>Interações ${b.interactions}<br>Pendências ${b.pending}</div><div><strong>DEPOIS</strong>Imagens ${a.imagesResolved}/${a.imagesTotal}<br>Interações ${a.interactions}<br>Pendências ${a.pending}</div>`;}}
function renderBuilderV3History(){const root=$('ub3History'),count=$('ub3SnapshotCount'),rows=U.v3.workspace?.snapshots||[];if(count)count.textContent=String(rows.length);if(!root)return;root.innerHTML=rows.length?rows.map(x=>`<div class="gi-ub3-history-row"><span><strong>${esc(x.label||x.type)}</strong><br><small>${esc(x.type)} · ${esc(String(x.createdAt||'').replace('T',' ').slice(0,16))}</small></span><button type="button" class="b95-button secondary" data-ub3-action="restore" data-snapshot-id="${esc(x.id)}">Restaurar</button></div>`).join(''):'<p class="beta95-muted">Nenhum checkpoint V3.</p>';}
function renderBuilderV3Director(){const target=$('ub3CreativeDirector'),source=$('creativeDirectorOutput');if(!target||!source||!source.innerHTML.trim())return;target.innerHTML=source.innerHTML;}
function renderBuilderV3(){ub3MountPreview();renderBuilderV3Stages();renderBuilderV3Tree();renderBuilderV3Inspector();renderBuilderV3Issues();renderBuilderV3Quality();renderBuilderV3History();renderBuilderV3Director();}
async function refreshBuilderV3(){if(!U.game||!$('universeBuilderV3')||U.v3.loading)return;U.v3.loading=true;try{const q=new URLSearchParams({language:$('universeLanguage').value});if(U.currentRevisionId)q.set('revisionId',U.currentRevisionId);const data=await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/v3/workspace?${q}`);U.v3.workspace=data;const selected=U.v3.selected?ub3FindNode(U.v3.selected.type,U.v3.selected.id):null;U.v3.selected=selected||ub3Nodes(data.structure||[])[0]||null;renderBuilderV3();}finally{U.v3.loading=false;}}
async function syncBuilderV3Issues(){if(!U.game)return;const authorization=U.i6?.current?.authorization?.entries||[],validation=U.editor?.validation||{};await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/v3/issues/sync`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({revisionId:U.currentRevisionId,authorization,validation})});U.v3.syncedKey=`${U.game}:${U.currentRevisionId||'latest'}`;await refreshBuilderV3();}
async function syncBuilderV3IssuesOnce(){const key=`${U.game}:${U.currentRevisionId||'latest'}`;if(!U.game||U.v3.syncedKey===key)return;try{await syncBuilderV3Issues();}catch(error){console.warn('[Universe Builder V3] issue sync',error?.message||error);}}
async function saveBuilderV3Section(){const n=U.v3.selected;if(!n||n.type!=='SECTION')return;await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/v3/sections/${encodeURIComponent(n.id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({revisionId:U.currentRevisionId,language:$('universeLanguage').value,title:$('ub3EditTitle').value,body:$('ub3EditBody').value,layoutVariant:$('ub3EditLayout').value})});notify('Seção salva e protegida contra sobrescrita automática.','good');await loadExperienceEditor();}
async function toggleBuilderV3Lock(){const n=U.v3.selected;if(!n)return;const next=!n.locked;await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/v3/components/${encodeURIComponent(n.type)}/${encodeURIComponent(n.id)}/lock`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({revisionId:U.currentRevisionId,locked:next,reason:next?'USER_LOCK':'USER_UNLOCK'})});n.locked=next;notify(next?'Componente protegido.':'Mudanças automáticas permitidas para este componente.','good');await refreshBuilderV3();}
async function createBuilderV3Snapshot(type='CHECKPOINT',label='Checkpoint manual'){await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/v3/snapshots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({revisionId:U.currentRevisionId,language:$('universeLanguage').value,type,label})});await refreshBuilderV3();}
async function restoreBuilderV3Snapshot(id){if(!id)return;if(!confirm('Restaurar este checkpoint? O estado atual poderá ser recuperado por um novo checkpoint de restauração.'))return;await createBuilderV3Snapshot('CHECKPOINT','Before restore');await GV.api(`/api/universe-builder-099/games/${encodeURIComponent(U.game)}/v3/snapshots/${encodeURIComponent(id)}/restore`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});notify('Checkpoint restaurado.','good');await loadExperienceEditor();}
async function runBuilderV3CreativeDirector(){await creativeDirectorI2();renderBuilderV3Director();}
async function autoRecoverBuilderV3(){if(!U.game)return;const before=ub3Metrics();await createBuilderV3Snapshot('AUTO_FIX','Before Auto-Recovery');notify('Auto-Recovery: analisando problemas recuperáveis...');const steps=[];try{await autoFixI5();steps.push('imagens/composição');}catch(error){steps.push(`auto-fix indisponível: ${error.message}`);}const motifs=U.i6?.current?.motifs||{};if(!Number(motifs.approved||0)){try{await discoverIdentityI6();steps.push('identidade');}catch{}}const inter=U.i6?.current?.interactions||{};if(!Number(inter.suggestions||0)&&!Number(inter.approved||0)){try{await discoverInteractionsI6();steps.push('interações');}catch{}}const safe=(U.i6?.current?.authorization?.entries||[]).filter(x=>Number(x.confidence||0)>=88);if(safe.length){try{await approveSafeI6();steps.push('autorizações seguras');}catch{}}await loadExperienceEditor();await syncBuilderV3Issues().catch(()=>{});const after=ub3Metrics();U.v3.beforeAfter={before,after};await createBuilderV3Snapshot('AUTO_FIX','After Auto-Recovery');renderBuilderV3Quality();notify(`Auto-Recovery concluído${steps.length?`: ${steps.join(' · ')}`:''}.`,'good');}
function selectBuilderV3(type,id){const n=ub3FindNode(type,id);if(!n)return;U.v3.selected=n;renderBuilderV3Tree();renderBuilderV3Inspector();if(innerWidth<=760)$('universeBuilderV3').dataset.mobilePanel='inspector';}
function bindBuilderV3(){const root=$('universeBuilderV3');if(!root)return;ub3MountPreview();root.addEventListener('click',e=>{const mobile=e.target.closest('[data-ub3-mobile]');if(mobile){root.dataset.mobilePanel=mobile.dataset.ub3Mobile;root.querySelectorAll('[data-ub3-mobile]').forEach(b=>b.classList.toggle('secondary',b!==mobile));return;}const select=e.target.closest('[data-ub3-select-id]');if(select){selectBuilderV3(select.dataset.ub3SelectType,select.dataset.ub3SelectId);return;}const vp=e.target.closest('[data-ub3-viewport]');if(vp){U.previewMode=vp.dataset.ub3Viewport;root.querySelectorAll('[data-ub3-viewport]').forEach(b=>b.classList.toggle('active',b===vp));if($('i4PreviewViewport'))$('i4PreviewViewport').dataset.mode=U.previewMode;regeneratePreviewI4().catch(error=>notify(error.message,'error'));return;}const action=e.target.closest('[data-ub3-action]');if(!action)return;e.preventDefault();const go=async()=>{switch(action.dataset.ub3Action){case'preview-refresh':return regeneratePreviewI4();case'sync-issues':return syncBuilderV3Issues();case'approve-safe':await approveSafeI6();return syncBuilderV3Issues();case'creative-director':return runBuilderV3CreativeDirector();case'auto-recover':return autoRecoverBuilderV3();case'snapshot':return createBuilderV3Snapshot();case'restore':return restoreBuilderV3Snapshot(action.dataset.snapshotId);case'save-section':return saveBuilderV3Section();case'toggle-lock':return toggleBuilderV3Lock();}};buttonBusy(action,true);go().catch(error=>notify(error.message||String(error),'error')).finally(()=>buttonBusy(action,false));});root.addEventListener('click',e=>{const section=e.target.closest('#ub3PreviewMount [data-section-key]');if(!section)return;const key=String(section.dataset.sectionKey||'');const node=ub3Nodes(U.v3.workspace?.structure||[]).find(x=>x.type==='SECTION'&&String(x.key)===key);if(node)selectBuilderV3(node.type,node.id);});}

function buttonBusy(button,busy,label='Processando...'){if(!button)return;button.disabled=busy;if(busy){button.dataset.ubLabel=button.textContent;button.textContent=label;}else if(button.dataset.ubLabel){button.textContent=button.dataset.ubLabel;delete button.dataset.ubLabel;}}
async function dispatchUniverseAction(button){const action=button.dataset.ubAction;if(!action)return;const run=async()=>{switch(action){case'open':return openUniverse();case'build':return startFoundation099();case'resume':return resumeFoundationI6();case'cancel':return cancelFoundation099();case'preview':await refreshFoundationPreview();return regeneratePreviewI4();case'publish':return publishFoundation099();case'enhance':if(!U.game)throw new Error('Selecione um jogo ou Experience.');if(button.disabled)return;$('enhanceDialogI6').showModal();return;case'enhance-start':return startEnhanceI6();case'view-content':{const a=$('advancedBuilder');a.open=true;renderAdvancedI5(U.editor);$('i4ResearchStage').scrollIntoView({behavior:'smooth',block:'start'});return;}case'resolve-images':return autoFixI5();case'identity-discover':return discoverIdentityI6();case'auto-fix':return autoFixI5();case'interaction-discover':return discoverInteractionsI6();case'interaction-view':$('i6InteractionsStage').scrollIntoView({behavior:'smooth',block:'start'});return;case'authorization-review':$('i6AuthorizationStage').scrollIntoView({behavior:'smooth',block:'start'});return;case'authorization-approve-safe':return approveSafeI6();case'preview-refresh':return regeneratePreviewI4();case'reload':return loadExperienceEditor();case'interaction-preview':return openInteractionPreviewI6(button.dataset.conceptId);case'authorization-preview':return openInteractionPreviewI6(button.dataset.i6AuthPreview);case'authorization-decision':return decideAuthorizationI6(button.dataset.authId,button.dataset.i6AuthDecision);case'interaction-approve':return approveInteractionI6();case'interaction-rebuild':return rebuildInteractionI6();case'interaction-discard':return discardInteractionI6();default:return;}};const slow=['build','resume','resolve-images','identity-discover','auto-fix','interaction-discover','authorization-approve-safe','preview-refresh','publish','enhance-start'].includes(action);if(slow)buttonBusy(button,true,action==='build'?'Construindo...':action==='resume'?'Retomando...':'Processando...');try{return await run();}finally{if(slow)buttonBusy(button,false);}}
function bindUniverseBuilder(){
  bindBuilderV3();
  document.addEventListener("visibilitychange",()=>{if(!document.hidden){poll();pollResearch();pollFoundation099();}else{clearTimeout(U.timer);clearTimeout(U.researchTimer);clearTimeout(U.foundationTimer);}});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-ub-action]');if(!b||b.disabled)return;e.preventDefault();dispatchUniverseAction(b).catch(error=>notify(error.message||String(error),'error'));});
  $("saveBlueprint").onclick=()=>saveBlueprint().catch(e=>notify(e.message,"error"));
  $("createManifest").onclick=()=>createManifest().catch(e=>notify(e.message,"error"));
  $("approveManifest").onclick=()=>approve().catch(e=>notify(e.message,"error"));
  $("startBuild").onclick=()=>start().catch(e=>notify(e.message,"error"));
  $("startResearch").onclick=()=>startResearch().catch(e=>notify(e.message,"error"));
  $("validateReadiness").onclick=()=>validateReadiness().catch(e=>notify(e.message,"error"));
  $("researchState").onclick=e=>{const b=e.target.closest("[data-research-action]");if(b)researchAction(b.dataset.researchAction).catch(error=>notify(error.message,"error"));};
  $("reloadExperienceEditor").onclick=()=>loadExperienceEditor().catch(e=>notify(e.message,"error"));
  $("saveVisualPolicy").onclick=()=>saveVisualPolicyI2().catch(e=>notify(e.message,"error"));
  $("addInteraction").onclick=()=>addInteractionI2().catch(e=>notify(e.message,"error"));
  $("applyInteractionPreset").onclick=()=>applyInteractionPresetI2().catch(e=>notify(e.message,"error"));
  $("creativeDirector").onclick=()=>creativeDirectorI2().catch(e=>notify(e.message,"error"));
  $("syncVisualAssets").onclick=()=>syncVisualAssetsI3().catch(e=>notify(e.message,"error"));
  $("syncImageVariablesI4").onclick=()=>syncImageVariablesI4().catch(e=>notify(e.message,"error"));
  $("refreshValidationI3").onclick=()=>refreshValidationI3().catch(e=>notify(e.message,"error"));
  $("addVisualAsset").onclick=()=>addVisualAssetI3().catch(e=>notify(e.message,"error"));
  $("visualAssetList").onclick=e=>{const b=e.target.closest("[data-i3-asset-action]");if(!b)return;const map={review:"REVIEWED",approve:"APPROVED",reject:"REJECTED",archive:"ARCHIVED"};updateVisualAssetApprovalI3(b.dataset.assetId,map[b.dataset.i3AssetAction]||"REVIEWED").catch(error=>notify(error.message,"error"));};
  $("interactionList").onclick=e=>{const b=e.target.closest("[data-i2-interaction-action]");if(!b)return;const id=b.dataset.interactionId,action=b.dataset.i2InteractionAction;if(action==='archive')archiveInteractionI2(id).catch(error=>notify(error.message,'error'));else updateInteractionStatusI2(id,action==='publish'?'PUBLISHED':'DRAFT').catch(error=>notify(error.message,'error'));};
  $("i4ImageVariables").onclick=e=>{const b=e.target.closest("[data-i4-image-action]");if(!b)return;const action=b.dataset.i4ImageAction,v=b.dataset.variableId,a=b.dataset.assetId;if(action==='search')searchImageVariableI4(v).catch(error=>notify(error.message,'error'));else if(action==='assign')assignImageVariableI4(v,a).catch(error=>notify(error.message,'error'));else if(action==='approve-assign')approveAssignImageVariableI4(v,a).catch(error=>notify(error.message,'error'));};
  $("i4ResearchContent").addEventListener("change",e=>{const select=e.target.closest("[data-i4-composition-select]");if(select)updateCompositionI4(select.dataset.i4CompositionSelect,select.value).catch(error=>notify(error.message,'error'));});
  document.querySelectorAll("[data-i4-preview-mode]").forEach(button=>button.addEventListener("click",()=>{U.previewMode=button.dataset.i4PreviewMode;document.querySelectorAll("[data-i4-preview-mode]").forEach(x=>x.classList.toggle('active',x===button));$("i4PreviewViewport").dataset.mode=U.previewMode;regeneratePreviewI4().catch(error=>notify(error.message,'error'));}));
  $("universeGame").addEventListener("change",()=>{U.foundationBuildId=null;U.foundationBuild=null;U.currentRevisionId=null;U.pipeline=null;$("foundationPreview").disabled=true;$("foundationPublish").disabled=true;$("foundationCancel").disabled=true;openUniverse().then(()=>recoverCurrentFoundationI6()).catch(e=>notify(e.message,"error"));});
  $('advancedBuilder').addEventListener('toggle',()=>{if($('advancedBuilder').open&&!U.advancedLoaded)renderAdvancedI5(U.editor);});
}
async function bootUniverseBuilder(){
  try{if(!window.GV)throw new Error("GAMEINDEX_SHELL_NOT_READY");bindUniverseBuilder();const entries=await games();if(entries.length){await openUniverse();await recoverCurrentFoundationI6();}}
  catch(error){notify(error.message||"UNIVERSE_BUILDER_BOOT_FAILED","error");}
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",bootUniverseBuilder,{once:true});else bootUniverseBuilder();
